def verify(witness):
    # pure function: returns True only if every required property is exactly verified
    try:
        entries = witness['entries']
        seen = set()
        for e in entries:
            n = e['n']
            expected = e['expected']
            if not isinstance(expected, bool):
                return False
            if not isinstance(n, int) or isinstance(n, bool):
                return False  # non-integer: fail closed
            if n < 0:
                return False  # unresolved sign: fail closed
            if n in seen:
                return False  # duplicate exponent
            seen.add(n)
            v = 2 ** n  # exact integer arithmetic
            m = v
            digits = []
            if m == 0:
                digits = [0]
            while m > 0:
                digits.append(m % 3)
                m = m // 3
            got = True
            for d in digits:
                if d == 2:
                    got = False
                elif d not in (0, 1):
                    return False  # impossible for base 3; fail closed
            if got != expected:
                return False
        return True
    except Exception:
        return False

WITNESS = {'entries': [
    {'n': 0, 'expected': True},
    {'n': 2, 'expected': True},
    {'n': 8, 'expected': True},
    {'n': 10, 'expected': False}
]}

RESULT = verify(WITNESS)  # must be True for PASS
